class Solution {
public:
    vector<int> pancakeSort(vector<int>& arr) {
        vector<int> res;
        int n = arr.size();
        for (int target = n; target > 1; --target) {
            int idx = find(arr.begin(), arr.end(), target) - arr.begin();
            if (idx == target - 1) continue;
            if (idx > 0) {
                res.push_back(idx + 1);
                reverse(arr.begin(), arr.begin() + idx + 1);
            }
            res.push_back(target);
            reverse(arr.begin(), arr.begin() + target);
        }
        return res;
    }
};

class Solution {
    private void reverse(int[] arr, int k) {
        int l = 0, r = k - 1;
        while (l < r) {
            int tmp = arr[l];
            arr[l] = arr[r];
            arr[r] = tmp;
            l++;
            r--;
        }
    }
    public List<Integer> pancakeSort(int[] arr) {
        List<Integer> res = new ArrayList<>();
        int n = arr.length;
        for (int target = n; target > 1; target--) {
            int idx = 0;
            while (arr[idx] != target) idx++;
            if (idx == target - 1) continue;
            if (idx > 0) {
                res.add(idx + 1);
                reverse(arr, idx + 1);
            }
            res.add(target);
            reverse(arr, target);
        }
        return res;
    }
}

var pancakeSort = function(arr) {
    const res = [];
    const n = arr.length;
    const reverse = (k) => {
        let l = 0, r = k - 1;
        while (l < r) {
            const tmp = arr[l];
            arr[l] = arr[r];
            arr[r] = tmp;
            l++;
            r--;
        }
    };
    for (let target = n; target > 1; target--) {
        const idx = arr.indexOf(target);
        if (idx === target - 1) continue;
        if (idx > 0) {
            res.push(idx + 1);
            reverse(idx + 1);
        }
        res.push(target);
        reverse(target);
    }
    return res;
};
